	[22015.0] = "{22015, \"血之眷赐\", \"吸血幽灵\", 2201, 0, 5, 0, 4, \"active_skill\", 0, 0, 1, 1, {220105,220111}, {}, 0, \"吸血幽灵善于从鲜血中汲取生命力，对敌方生命比例最低的单体造成【等同佩罗娜攻击力540%+目标生命值5%】的物理伤害（不超过佩罗娜攻击力的10倍），同时为己方生命值最低的单位回复等同伤害100%的生命值\", \"初始激活\", \"升级条件：<div fontcolor=45a536>已达最高等级</div>\", \"2201\", 0, 1, 1, {}, 0, 1, 0, 0}",
	[23015.0] = "{23015, \"大收割\", \"收割幽灵\", 2301, 0, 5, 0, 4, \"active_skill\", 0, \"min_hp_per\", 1, 1, {230105}, {}, 0, \"对敌方生命比例最低的单位造成【等同佩罗娜攻击力1000%+目标生命值10%】的魔法伤害且无视目标20%防御（不超过佩罗娜攻击力的15倍）\", \"初始激活\", \"升级条件：<div fontcolor=45a536>已达最高等级</div>\", \"2301\", 0, 2, 1, {}, 0, 0, 0, 0}",
