	[24004.0] = "{24004, \"大收割\", \"收割幽灵\", 2400, 0, 4, 0, 0, \"passive_skill\", 0, 0, 1, 1, {240011}, {}, 0, \"该状态下的单位受到体术（物理）攻击时，30%概率令攻击者处于2回合的【禁锢】状态，护盾效果持续2回合\", \"\", \"\", \"20230\", 0, 1, 1, {}, 0, 0, 0, 0}",
