	[24022.0] = "{24022, \"浪漫情绪\", \"浪漫幽灵\", 2402, 24023, 2, 0, 4, \"active_skill\", 0, 0, 2, 1, {240202,240212,240221}, {}, 0, \"为己方全体回复【等同佩罗娜生命值67%+目标生命值6%】生命值，同时对生命值低于30%的目标附加【不屈】效果，持续2回合：【不屈】状态下首次被击杀必定复活且保留少量生命值，受【禁止复活】状态影响\", \"初始激活\", \"升级条件：<div fontcolor=45a536>神兽吞噬</div>升级\", \"2302\", 0, 1, 1, {}, 0, 1, 0, 0}",
